const tabId = 118779795;

const details = await browserjs(tabId, () => {
  // Let's inspect the exact list items
  const items = Array.from(document.querySelectorAll('li[id^="issue_"], li[class*="Box-row"], [data-testid="issue-list-item"], li')).filter(el => {
    return el.querySelector('a[href*="/issues/"]');
  });

  const parsed = [];
  for (const item of items) {
    const issueLink = item.querySelector('a[href*="/alibaba/open-code-review/issues/"]');
    if (!issueLink) continue;
    const href = issueLink.href;
    const match = href.match(/\/issues\/(\d+)$/);
    if (!match) continue;
    const num = match[1];

    // Find comment count
    // Often there is an aria-label with comments or an svg icon with comment text
    let comments = 0;
    const commentEl = item.querySelector('a[aria-label*="comment"], [aria-label*="comment"], span[aria-label*="comment"], [data-testid="comments-count"]');
    if (commentEl) {
      const text = commentEl.getAttribute('aria-label') || commentEl.textContent;
      const m = text.match(/(\d+)\s+comment/);
      if (m) comments = parseInt(m[1], 10);
    } else {
      // search item text
      const m = item.textContent.match(/(\d+)\s+comments?/);
      if (m) comments = parseInt(m[1], 10);
    }

    const isPinned = item.closest('.pinned-issue-item') !== null || item.classList.contains('pinned-issue-item') || item.innerText.includes('Pinned');

    parsed.push({
      num,
      title: issueLink.textContent.trim(),
      href,
      comments,
      isPinned,
      rawText: item.innerText.replace(/\s+/g, ' ').slice(0, 150)
    });
  }

  // Deduplicate by num
  const unique = [];
  const seen = new Set();
  for (const p of parsed) {
    if (!seen.has(p.num)) {
      seen.add(p.num);
      unique.push(p);
    }
  }

  return unique;
});

console.log("Parsed issues count:", details.length);
details.sort((a, b) => b.comments - a.comments);
console.log(JSON.stringify(details.slice(0, 10), null, 2));

