const tabId = 118779795;

const checkComments = await browserjs(tabId, () => {
  // Let's check for any buttons like "Load more" or hidden timeline items
  const buttons = Array.from(document.querySelectorAll('button')).map(b => b.textContent?.trim()).filter(t => t?.toLowerCase().includes('more') || t?.toLowerCase().includes('hidden') || t?.toLowerCase().includes('comment'));

  // Also check if GitHub has an embedded JSON script tag for the issue data (e.g. data-target="react-app.embeddedData" or similar)
  const scriptTags = Array.from(document.querySelectorAll('script[type="application/json"]')).map(s => {
    try {
      const parsed = JSON.parse(s.textContent);
      return { id: s.id, keys: Object.keys(parsed), textSample: s.textContent.slice(0, 200) };
    } catch {
      return null;
    }
  }).filter(Boolean);

  return {
    buttons,
    scriptTags
  };
});

