        const obj = JSON.parse(s.textContent);
        return {
          hasIssue: !!obj.payload?.issue,
          issueKeys: obj.payload?.issue ? Object.keys(obj.payload.issue) : null,
          totalComments: obj.payload?.issue?.totalCommentsCount || obj.payload?.issue?.comments?.totalCount,
          objSnippet: JSON.stringify(obj).slice(0, 500)
        };
      } catch (e) {
        // continue
      }
    }
  }
  return null;
});

